# -*- coding: utf-8 -*-
from _lib import s
S = [
 s(1, 'title', 'Aircraft Systems, Analog Systems & Digital Systems: Numbering systems',
   'Title slide: "Aircraft Systems, Analog Systems & Digital Systems", subtitle "Numbering systems". Lecturer: Pham Duy An, Department of Technology and Engineering. USTH logo and a photo of a glass cockpit with several flat displays.',
   'Slide tiêu đề: "Aircraft Systems, Analog Systems & Digital Systems", phụ đề "Numbering systems" (các hệ đếm). Giảng viên: Pham Duy An, Khoa Công nghệ và Kỹ thuật. Có logo USTH và ảnh buồng lái kính với nhiều màn hình phẳng.'),
 s(2, 'content', 'Section Outline',
   'Outline: Introduction; review the decimal number system; binary number system (counting, weighting structure, conversion with other number systems, binary arithmetic); hexadecimal numbers (counting, weighting structure, conversion); octal numbers (counting, weighting structure, conversion); binary decimal code (BCD).',
   'Dàn bài: giới thiệu; ôn hệ thập phân; hệ nhị phân (đếm, cấu trúc trọng số, đổi sang hệ khác, số học nhị phân); số thập lục phân (đếm, trọng số, đổi); số bát phân (đếm, trọng số, đổi); mã thập phân mã hoá nhị phân (BCD).'),
 s(3, 'content', 'Applications of number systems in A320',
   'Infographic "Applications of number systems in A320": four columns. 1 Binary (base 2): all data inside computers (FMGC, FWC, SDAC) is processed in binary; sensor signals are converted to binary by an ADC; buses (ARINC 429, AFDX/Ethernet) carry binary data. Example: decimal 10,000 is 0010 0111 0001 0000 in 16-bit binary; flow sensor, A/D, computer, display shows 10000 FT. 2 Octal (base 8): a shorthand for binary, used in status and address displays; example 110 101 111 100 (binary) = 6 5 7 4 (octal); a system status page shows FMGC 1 0127 OK, FMGC 2 0136 OK, FAC 1 0045 OK, SEC 1 0072 OK. 3 BCD: each decimal digit coded separately in 4 bits, used on 7-segment displays (ECAM, EWD, clocks); example 250 is 0010 0101 0000; an ECAM page shows N1 85.6 %, EGT 650 C, FOB 6350 KG, LDG ELEV 250 FT; FL250 in BCD 0010 0101 0000. 4 Hexadecimal (base 16): compact form for addresses, error codes and data words, one hex digit equals 4 bits; example 1010 1100 1101 1110 (binary) = ACDE (hex); a BITE message shows L/G COMP FAULT, FAULT CODE 0xACDE, REF 32-42-00; the bus data is binary, shown in hex for logs. A summary strip repeats the four systems with 0 1, 6574 (octal), 250 (BCD), ACDE (hex).',
   'Infographic "Ứng dụng của các hệ đếm trên A320" gồm bốn cột. 1 Nhị phân (cơ số 2): mọi dữ liệu trong máy tính (FMGC, FWC, SDAC) được xử lý dạng nhị phân; tín hiệu cảm biến được ADC đổi sang nhị phân; bus (ARINC 429, AFDX/Ethernet) truyền dữ liệu nhị phân. Ví dụ: thập phân 10.000 là 0010 0111 0001 0000 ở nhị phân 16 bit; luồng cảm biến, A/D, máy tính, màn hình hiện 10000 FT. 2 Bát phân (cơ số 8): cách viết ngắn của nhị phân, dùng cho trang trạng thái và địa chỉ; ví dụ 110 101 111 100 (nhị phân) = 6 5 7 4 (bát phân); trang trạng thái hệ thống hiện FMGC 1 0127 OK, FMGC 2 0136 OK, FAC 1 0045 OK, SEC 1 0072 OK. 3 BCD: mỗi chữ số thập phân mã riêng bằng 4 bit, dùng cho màn hình 7 đoạn (ECAM, EWD, đồng hồ); ví dụ 250 là 0010 0101 0000; trang ECAM hiện N1 85,6 %, EGT 650 C, FOB 6350 KG, LDG ELEV 250 FT; FL250 dạng BCD là 0010 0101 0000. 4 Thập lục phân (cơ số 16): dạng gọn cho địa chỉ, mã lỗi và từ dữ liệu, một chữ số hex bằng 4 bit; ví dụ 1010 1100 1101 1110 (nhị phân) = ACDE (hex); thông báo BITE hiện L/G COMP FAULT, FAULT CODE 0xACDE, REF 32-42-00; dữ liệu trên bus là nhị phân, hiển thị dạng hex để ghi nhật ký. Dải tóm tắt ở cuối nhắc lại bốn hệ với 0 1, 6574 (bát phân), 250 (BCD), ACDE (hex).',
   numbers=['10.000 thập phân = 0010 0111 0001 0000 (nhị phân 16 bit)', '110 101 111 100 nhị phân = 6574 bát phân', 'BCD của 250 = 0010 0101 0000', '1010 1100 1101 1110 nhị phân = ACDE hex'],
   issues=['Đã kiểm bằng tính: 10 000 = 0x2710 = 0010 0111 0001 0000; 110 101 111 100 = 6574 (bát phân); 1010 1100 1101 1110 = ACDE; BCD của 250 = 0010 0101 0000. Cả bốn ví dụ đúng.',
           'Nghi vấn: cột nhị phân ghi dữ liệu trên bus gồm "ARINC 429, AFDX/Ethernet" trong khung A320, trong khi Module 05 (theo Tooley) gắn AFDX với A380/A350. Chưa kiểm bằng tài liệu hãng nên chỉ ghi nghi vấn, cần hỏi giảng viên.']),
 s(4, 'content', 'Introduction (analog and digital representation)',
   'Analog representation is a continuous value with respect to time and characterises an analog signal. Digital representation is a discrete value with respect to time and characterises a digital signal. Figures: an analog sine wave between +120 V and -120 V against time, captioned "analog signal: it consists of a continuously changing voltage level"; a digital pulse train 0 1 0 0 1 0 1 1 between 0 V and +5 V, captioned "Digital signal: it consists of series of discrete voltage that alternate between logic 0 and 1". Advantages of digital compared to analog: possibility of encoding of digital data (safety); only two levels of amplitude, easier reconstitution of the digital signal (reliability); precise value always in time (reliability); compatible with computers; stable and more rapid than analog system.',
   'Biểu diễn tương tự là giá trị liên tục theo thời gian, đặc trưng cho tín hiệu tương tự. Biểu diễn số là giá trị rời rạc theo thời gian, đặc trưng cho tín hiệu số. Hình: sóng sin tương tự giữa +120 V và -120 V theo thời gian, chú thích "tín hiệu tương tự: gồm mức điện áp biến đổi liên tục"; dãy xung số 0 1 0 0 1 0 1 1 giữa 0 V và +5 V, chú thích "tín hiệu số: gồm chuỗi điện áp rời rạc xen kẽ giữa logic 0 và 1". Ưu điểm của số so với tương tự: có thể mã hoá dữ liệu số (an toàn); chỉ hai mức biên độ nên dễ khôi phục tín hiệu số (tin cậy); giá trị chính xác luôn theo thời gian (tin cậy); tương thích với máy tính; ổn định và nhanh hơn hệ tương tự.',
   numbers=['sóng tương tự +120 V đến -120 V', 'tín hiệu số 0 V và +5 V, chuỗi 0 1 0 0 1 0 1 1']),
 s(5, 'content', 'Introduction (aircraft digital systems)',
   'Bullets: aircraft rely more and more on digital systems; information within an aircraft digital system is a sequence of 1s and 0s known as binary data; digital quantities can be kept at very high accuracy and measured and manipulated at very high speed; the binary system is widely used in digital computers and digital electronics. Figures: an aircraft outline with flight-control data buses (primary flight computers, autopilot director computers, air data reference unit, actuator control electronics) and systems data buses (engine data interface, aircraft information management system, flap/slat electronics unit, proximity electronics unit); a digital signal drawn as pulses of 1 and 0; a block diagram: input (a temperature, pressure, air flow, linear motion or rotation) goes through sensing the signal, conditioning the signal, converting the signal analog-to-digital, then digital system processing, then converting digital-to-analog, conditioning, transducing to a useful output (a solenoid, heater, motor or cooler); the converted signals are an electrical voltage or current.',
   'Các ý: máy bay ngày càng dựa vào hệ thống số; thông tin trong hệ thống số của tàu bay là chuỗi các số 1 và 0 gọi là dữ liệu nhị phân; đại lượng số có thể giữ độ chính xác rất cao và đo, xử lý với tốc độ rất cao; hệ nhị phân dùng rộng rãi trong máy tính số và điện tử số. Hình: sơ đồ tàu bay với các bus dữ liệu điều khiển bay (máy tính bay chính, máy tính bay tự động, khối dữ liệu không khí, điện tử điều khiển cơ cấu) và bus dữ liệu hệ thống (giao diện dữ liệu động cơ, hệ quản lý thông tin tàu bay, khối điện tử cánh tà/cánh slat, khối điện tử cảm biến tiệm cận); tín hiệu số vẽ bằng các xung 1 và 0; sơ đồ khối: đầu vào (nhiệt độ, áp suất, lưu lượng khí, chuyển động thẳng hoặc quay) qua cảm nhận, điều hoà, đổi tương tự sang số, rồi xử lý hệ thống số, rồi đổi số sang tương tự, điều hoà, chuyển đổi thành đầu ra hữu ích (van điện từ, bộ sưởi, động cơ hoặc bộ làm mát); tín hiệu đã đổi là điện áp hoặc dòng điện.'),
 s(6, 'content', 'Introduction (converting between number systems)',
   'Binary numbers are not very convenient for human use, so convert them to forms that are easier to recognise and manipulate. A subscript distinguishes number systems: subscript 8 for octal (75)8, subscript 10 for decimal (75)10, subscript 16 for hexadecimal (75)16. A diagram shows four ellipses, Decimal numbers (9856)10, Hexadecimal numbers (A89DE)16, Binary numbers (101010101)2 and Octal numbers (7537)8, joined by arrows labelled Conversion; red solid arrows join binary with each of the others and dotted arrows join the other pairs directly.',
   'Số nhị phân không thuận tiện cho con người nên đổi sang dạng dễ nhận biết và xử lý hơn. Chỉ số dưới phân biệt hệ đếm: 8 cho bát phân (75)8, 10 cho thập phân (75)10, 16 cho thập lục phân (75)16. Sơ đồ có bốn hình elip: số thập phân (9856)10, số thập lục phân (A89DE)16, số nhị phân (101010101)2 và số bát phân (7537)8, nối bằng các mũi tên "Conversion"; mũi tên đỏ liền nối nhị phân với từng hệ còn lại, mũi tên chấm nối trực tiếp các cặp khác.',
   numbers=['(9856)10', '(A89DE)16', '(101010101)2', '(7537)8', '(75)8, (75)10, (75)16']),
 s(7, 'content', 'Decimal number system',
   'Decimal numbers are used every day. The decimal system consists of ten digits, 0 through 9. The position of each digit indicates the magnitude of the quantity represented and can be assigned a weight. The weights for whole numbers are positive powers of ten that increase from right to left. Example: express the decimal number 52 as a sum of each digit: the digit 5 has a weight of 10 (10^1) and the digit 2 has a weight of 1 (10^0), so 52 = (5 x 10^1) + (2 x 10^0) = 50 + 2.',
   'Số thập phân được dùng hằng ngày. Hệ thập phân gồm mười chữ số, từ 0 đến 9. Vị trí của mỗi chữ số cho biết độ lớn của đại lượng và có thể gán trọng số. Trọng số của số nguyên là các luỹ thừa dương của mười tăng từ phải sang trái. Ví dụ: biểu diễn số thập phân 52 thành tổng các chữ số: chữ số 5 có trọng số 10 (10^1), chữ số 2 có trọng số 1 (10^0), nên 52 = (5 x 10^1) + (2 x 10^0) = 50 + 2.',
   formulas=['52 = (5 x 10^1) + (2 x 10^0) = 50 + 2']),
 s(8, 'content', 'Applications of the decimal number system in the Airbus A320',
   'Infographic with an A320 in the middle and five panels. 1 Flight instruments (EFIS/ND/PFD): most parameters in decimal; speed 250 kt, altitude 10,000 ft, heading 090 degrees, altitude tape 10200 to 9800. 2 Flight management system: from EGLL to LFPG, DIST 343 NM, TIME 00:47, FUEL 3200 KG, FL330, COST INDEX 45. 3 Autopilot/FCU (MCP): SPD 250, HDG 090, ALT 10000, V/S +1500; speed 250 kt, heading 090, altitude 10,000 ft, vertical speed +1500 ft/min. 4 System monitoring (ECAM): N1 88.5 %, EGT 610 C, N2 92.1 %, FF 1250 KG/H, OIL QTY 17.5 QT, VIB 0.6 N1, TAT -15 C. 5 Maintenance and weight data: MTOW 77,000 kg, MLW 64,500 kg, MZFW 61,500 kg, FUEL CAPACITY 23,860 KG, CHECK INTERVAL 750 FH; weights, fuel and intervals are expressed in decimal. A bottom bar says the decimal system is human-friendly, intuitive and suited to representing real-world quantities used by pilots, engineers and maintenance crews.',
   'Infographic có một chiếc A320 ở giữa và năm khung. 1 Dụng cụ bay (EFIS/ND/PFD): hầu hết thông số ở dạng thập phân; tốc độ 250 kt, độ cao 10.000 ft, hướng 090 độ, thang độ cao 10200 đến 9800. 2 Hệ quản lý bay: từ EGLL đến LFPG, DIST 343 NM, TIME 00:47, FUEL 3200 KG, FL330, COST INDEX 45. 3 Lái tự động/FCU (MCP): SPD 250, HDG 090, ALT 10000, V/S +1500; tốc độ 250 kt, hướng 090, độ cao 10.000 ft, tốc độ lên xuống +1500 ft/min. 4 Giám sát hệ thống (ECAM): N1 88,5 %, EGT 610 C, N2 92,1 %, FF 1250 KG/H, OIL QTY 17,5 QT, VIB 0,6 N1, TAT -15 C. 5 Dữ liệu bảo dưỡng và khối lượng: MTOW 77.000 kg, MLW 64.500 kg, MZFW 61.500 kg, FUEL CAPACITY 23.860 KG, CHECK INTERVAL 750 FH; khối lượng, nhiên liệu và chu kỳ ghi dạng thập phân. Dải cuối nói hệ thập phân thân thiện với con người, trực quan và hợp để biểu diễn các đại lượng thực mà phi công, kỹ sư và tổ bảo dưỡng dùng.',
   numbers=['MTOW 77.000 kg', 'MLW 64.500 kg', 'MZFW 61.500 kg', 'FUEL CAPACITY 23.860 KG', 'CHECK INTERVAL 750 FH'],
   issues=['Nghi vấn đơn vị: bảng ghi "FUEL CAPACITY 23,860 KG" trong khi phần chú thích nói khối lượng và nhiên liệu tính bằng kg; con số 23 860 thường được dùng như sức chứa theo lít, nhưng thư mục không có tài liệu hãng để xác nhận. Chỉ ghi nghi vấn.']),
 s(9, 'content', 'Binary numbers (weights and binary to decimal)',
   'The binary system has two digits, 0 and 1 (bits). Weights are powers of two and the position of a 1 or 0 gives its weight. The rightmost bit is the LSB, the leftmost is the MSB (figure: binary number 110100 with MSB and LSB arrows). Binary to decimal: add the weights of the bits that are 1 and discard the weights of the bits that are 0. Example: 11011010 = (1x2^7)+(1x2^6)+(0x2^5)+(1x2^4)+(1x2^3)+(0x2^2)+(1x2^1)+(0x2^0) = 128+64+16+8+2 = 218. Table of binary weights: 2^8 = 256, 2^7 = 128, 2^6 = 64, 2^5 = 32, 2^4 = 16, 2^3 = 8, 2^2 = 4, 2^1 = 2, 2^0 = 1.',
   'Hệ nhị phân có hai chữ số 0 và 1 (bit). Trọng số là các luỹ thừa của hai và vị trí của bit 1 hoặc 0 cho biết trọng số. Bit ngoài cùng bên phải là LSB, ngoài cùng bên trái là MSB (hình: số nhị phân 110100 có mũi tên MSB và LSB). Đổi nhị phân sang thập phân: cộng trọng số các bit bằng 1, bỏ trọng số các bit bằng 0. Ví dụ: 11011010 = 128+64+16+8+2 = 218. Bảng trọng số nhị phân: 2^8 = 256 đến 2^0 = 1.',
   formulas=['11011010 = 2^7 + 2^6 + 2^4 + 2^3 + 2^1 = 128 + 64 + 16 + 8 + 2 = 218'], numbers=['11011010 nhị phân = 218 thập phân'], issues=['Đã kiểm: 128+64+16+8+2 = 218. Đúng.']),
 s(10, 'content', 'Applications of binary system in A320',
   'Infographic with six panels around an A320. 1 Data processing in computers: FMGC, FWC and SDAC represent and process information in binary; example altitude 10,000 ft = 0010 0111 0001 0000 in 16-bit binary; the computer adds, subtracts and compares with AND, OR, NOT and XOR gates. Flight control computer (FCC): control laws, sensor data and pilot input with binary calculations. Air data and inertial reference system (ADIRU): converts analog measurements to digital data. Engines (FADEC): monitors and controls the engine with digital signals. Data bus (ARINC 429 / AFDX): transmits binary data. 2 Sensor signals converted to binary: sensor, ADC (A/D), digital data; example air speed 250 kt = 250 decimal = 11111010 binary (8 bit). 3 Display information: ALT on PFD, displayed 10,000, binary data sent to the display 0010 0111 0001 0000. 4 Communication between systems: ARINC 429 data word of 32 bits with fields Label (8 bit), SDI (2 bit), Data (19 bit), SSM (2 bit), Parity (1 bit); example ALT = 10,000 ft sent from ADIRU to PFD as 10101100 | 11 | 01001110000100000 | 01 | 0. 5 System status and discrete signals: gear downlock 0 = unlocked, 1 = locked; spoiler position 0 = retracted, 1 = extended; master warning 0 = no warning, 1 = warning; pushbutton (TAWS INOP) to input module to computer to system action. Summary strip and closing line: binary enables fast, reliable and noise-immune processing, essential for safe flight.',
   'Infographic sáu khung quanh một chiếc A320. 1 Xử lý dữ liệu trong máy tính: FMGC, FWC, SDAC biểu diễn và xử lý thông tin ở dạng nhị phân; ví dụ độ cao 10.000 ft = 0010 0111 0001 0000 ở nhị phân 16 bit; máy tính cộng, trừ, so sánh bằng cổng AND, OR, NOT, XOR. Máy tính điều khiển bay (FCC): luật điều khiển, dữ liệu cảm biến và lệnh phi công bằng phép tính nhị phân. Khối dữ liệu không khí và quán tính (ADIRU): đổi phép đo tương tự thành dữ liệu số. Động cơ (FADEC): giám sát và điều khiển bằng tín hiệu số. Bus dữ liệu (ARINC 429 / AFDX): truyền dữ liệu nhị phân. 2 Tín hiệu cảm biến đổi sang nhị phân: cảm biến, ADC, dữ liệu số; ví dụ tốc độ 250 kt = 250 thập phân = 11111010 nhị phân (8 bit). 3 Thông tin hiển thị: ALT trên PFD hiện 10.000, dữ liệu nhị phân gửi tới màn hình 0010 0111 0001 0000. 4 Liên lạc giữa các hệ: từ dữ liệu ARINC 429 dài 32 bit gồm Label (8 bit), SDI (2 bit), Data (19 bit), SSM (2 bit), Parity (1 bit); ví dụ ALT = 10.000 ft gửi từ ADIRU tới PFD là 10101100 | 11 | 01001110000100000 | 01 | 0. 5 Trạng thái hệ thống và tín hiệu rời rạc: càng chốt bánh 0 = mở, 1 = khoá; cánh gió 0 = thu, 1 = xả; cảnh báo chính 0 = không, 1 = có; nút bấm (TAWS INOP) vào mô-đun vào rồi máy tính rồi hành động của hệ. Dải tóm tắt và dòng cuối: nhị phân cho xử lý nhanh, tin cậy, chống nhiễu, thiết yếu cho bay an toàn.',
   numbers=['10.000 ft = 0010 0111 0001 0000', '250 = 11111010', 'từ ARINC 429: Label 10101100, SDI 11, Data 01001110000100000, SSM 01, Parity 0'],
   issues=['Đã kiểm: 250 = 11111010 và 10.000 = 0010 0111 0001 0000 đúng.',
           'Không khớp trên slide 10 (đọc ở độ phóng đại 5 lần): khung từ ARINC 429 ghi trường Data dài 19 bit, nhưng ví dụ "01001110000100000" chỉ có 17 chữ số và dãy mẫu "1011010101111011" chỉ có 16 chữ số. Ví dụ ALT = 10.000 ft có tổng 8 + 2 + 17 + 2 + 1 = 30 bit thay vì 32 bit; 17 chữ số này cũng không phải 10.000 (10011100010000) dịch bit theo cách đơn giản nào. Không dùng ví dụ này làm số liệu; từ ARINC 429 chuẩn xem Module 05.',
           'Nghi vấn như slide 3: AFDX nằm trong khung A320.']),
 s(11, 'content', 'Binary numbers (counting)',
   'Counting in binary: begin 0, 1; a second position is required: 10, 11; then a third position: 100, 101, 110, 111. With n bits you can count up to 2^n - 1; example: with five bits you can count from zero to thirty-one. Table: a binary count of zero through fifteen in four bits (0 = 0000 ... 15 = 1111).',
   'Đếm nhị phân: bắt đầu 0, 1; cần vị trí thứ hai: 10, 11; rồi vị trí thứ ba: 100, 101, 110, 111. Với n bit đếm được tới 2^n - 1; ví dụ năm bit đếm từ 0 đến 31. Bảng: đếm nhị phân từ 0 đến 15 bằng bốn bit (0 = 0000 ... 15 = 1111).',
   formulas=['2^n - 1'], numbers=['5 bit: 0 đến 31', '4 bit: 0000 đến 1111 (0 đến 15)']),
 s(12, 'content', 'Binary numbers (decimal to binary: sum of weights)',
   'Decimal to binary conversion by two methods: sum of weights and repeated division by 2. Sum of weights: find the set of binary weights whose sum equals the decimal number. Example: 11 = 8 + 2 + 1 = 2^3 + 2^1 + 2^0, so the binary number of decimal 11 is 1011. The table of binary weights 256 down to 1 is repeated.',
   'Đổi thập phân sang nhị phân bằng hai cách: tổng trọng số và chia 2 liên tiếp. Tổng trọng số: tìm tập trọng số nhị phân có tổng bằng số thập phân. Ví dụ: 11 = 8 + 2 + 1 = 2^3 + 2^1 + 2^0, nên số nhị phân của thập phân 11 là 1011. Bảng trọng số nhị phân từ 256 đến 1 được nhắc lại.',
   formulas=['11 = 8 + 2 + 1 = 2^3 + 2^1 + 2^0'], numbers=['11 thập phân = 1011 nhị phân']),
 s(13, 'content', 'Binary numbers (decimal to binary: repeated division by 2)',
   'Repeated division by 2 method. Step 1: divide 11 by 2. Step 2: divide each resulting quotient by 2 until there is a 0 whole-number quotient. The remainders form the binary number; the first remainder is the least significant bit and the last is the most significant bit. Worked: 11/2 = 5 remainder 1 (low significant bit); 5/2 = 2 remainder 1; 2/2 = 1 remainder 0; 1/2 = 0 remainder 1 (most significant bit); stop when the whole-number quotient is 0. Binary number: 1011.',
   'Phương pháp chia 2 liên tiếp. Bước 1: chia 11 cho 2. Bước 2: chia từng thương cho 2 cho đến khi thương nguyên bằng 0. Các số dư tạo thành số nhị phân; số dư đầu là bit có trọng số nhỏ nhất, số dư cuối là bit có trọng số lớn nhất. Ví dụ: 11/2 = 5 dư 1 (bit thấp); 5/2 = 2 dư 1; 2/2 = 1 dư 0; 1/2 = 0 dư 1 (bit cao nhất); dừng khi thương nguyên bằng 0. Số nhị phân: 1011.',
   numbers=['11 chia 2 liên tiếp cho 1011'], issues=['Đã kiểm: 11 = 1011 nhị phân. Đúng.']),
 s(14, 'content', 'Binary numbers (binary arithmetic and half adder)',
   'Binary arithmetic is essential in all digital computers: binary addition, subtraction, multiplication and division. Figure: a half-adder logic circuit made of an XOR gate giving the sum, sum = A XOR B = A B-bar + A-bar B, and an AND gate giving the carry, Cout = AB. Three tables: four rules for adding binary digits (0+0 = 0 sum of 0 carry 0; 0+1 = 1 carry 0; 1+0 = 1 carry 0; 1+1 = 0 sum of 0 with a carry of 1); four rules for subtracting (0-0 = 0; 1-1 = 0; 1-0 = 1; 10-1 = 1; and 0-1 with a borrow of 1); four rules for multiplying (0x0 = 0; 0x1 = 0; 1x0 = 0; 1x1 = 1).',
   'Số học nhị phân thiết yếu trong mọi máy tính số: cộng, trừ, nhân, chia nhị phân. Hình: mạch bán cộng gồm cổng XOR cho tổng, tổng = A XOR B = A B-gạch + A-gạch B, và cổng AND cho nhớ, Cout = AB. Ba bảng: bốn quy tắc cộng (0+0 = 0 nhớ 0; 0+1 = 1 nhớ 0; 1+0 = 1 nhớ 0; 1+1 = 0 nhớ 1); bốn quy tắc trừ (0-0 = 0; 1-1 = 0; 1-0 = 1; 10-1 = 1; và 0-1 mượn 1); bốn quy tắc nhân (0x0 = 0; 0x1 = 0; 1x0 = 0; 1x1 = 1).',
   formulas=['\\Sigma = A \\oplus B = A\\overline{B} + \\overline{A}B', 'C_{out} = AB'],
   issues=['Bảng trừ liệt kê "10 - 1 = 1" và "0 - 1 với mượn 1" ở cùng một dòng; thứ tự và cách viết hơi gộp nhưng nội dung đúng.']),
 s(15, 'content', 'Binary numbers (worked arithmetic examples)',
   'Example: a) add 011 + 001; b) subtract 101 - 011; c) multiply 101 x 111. Solution a: columns with two carries, 011 plus 001 gives 100. Solution b: 101 - 011 = 010. Solution c: partial products 111, 000, 111 added give 100011, shown beside the decimal check 7 x 5 = 35.',
   'Ví dụ: a) cộng 011 + 001; b) trừ 101 - 011; c) nhân 101 x 111. Lời giải a: các cột có hai lần nhớ, 011 cộng 001 cho 100. Lời giải b: 101 - 011 = 010. Lời giải c: các tích riêng 111, 000, 111 cộng lại cho 100011, kèm phép kiểm thập phân 7 x 5 = 35.',
   formulas=['011 + 001 = 100', '101 - 011 = 010', '111 x 101 = 100011'], numbers=['3 + 1 = 4', '5 - 3 = 2', '7 x 5 = 35'], issues=['Đã kiểm: 011+001 = 100 (3+1 = 4), 101-011 = 010 (5-3 = 2), 111x101 = 100011 (7x5 = 35). Cả ba đúng.']),
 s(16, 'content', 'Hexadecimal numbers',
   'Hexadecimal has 16 characters and is used to display or write binary numbers. Computers and microprocessors understand only 1s and 0s, which is needed when programming in machine language; writing a sixteen-bit instruction in 1s and 0s is far less efficient than in hexadecimal. Hexadecimal is widely used in computer and microprocessor applications. The system uses the digits 0-9 and the letters A-F. Counting with two hexadecimal digits reaches FF16, decimal 255: 0, 1, 2 ... 9, A, B, C, D, E, F, 10, 11, 12, 13 ... 19, 1A, 1B, 1C, 1D, 1E, 1F. Table of decimal 0-15 with binary 0000-1111 and hex 0-F.',
   'Hệ thập lục phân có 16 ký tự, dùng để hiển thị hoặc viết số nhị phân. Máy tính và vi xử lý chỉ hiểu 1 và 0, cần khi lập trình ngôn ngữ máy; viết lệnh mười sáu bit bằng 1 và 0 kém hiệu quả hơn nhiều so với dùng hex. Thập lục phân dùng rộng rãi trong máy tính và vi xử lý. Hệ gồm chữ số 0-9 và chữ cái A-F. Đếm bằng hai chữ số hex tới FF16, tức thập phân 255: 0, 1, 2 ... 9, A, B, C, D, E, F, 10, 11, 12, 13 ... 19, 1A, 1B, 1C, 1D, 1E, 1F. Bảng thập phân 0-15 với nhị phân 0000-1111 và hex 0-F.',
   numbers=['FF16 = 255'], issues=['Đã kiểm: FF16 = 15x16 + 15 = 255. Đúng.']),
 s(17, 'content', 'Applications of the hexadecimal number system in the Airbus A320',
   'Infographic with five panels. 1 ARINC 429 labels: table PARAMETER, LABEL (HEX), DESCRIPTION: air speed 0x00A, altitude 0x020, heading 0x082, vertical speed 0x07F, OAT 0x0F2; example airspeed label = 0x00A. 2 Data words on ARINC 429: fields SDI (2 bits), DATA (19 bits), SSM (2 bits), PARITY (1 bit), S (1 bit) from bit 31 to bit 0; example data word (hex) 0x1A3F5BCD with SDI = 0x1, Data = 0xA3F5B, SSM = 0x2, Parity = 0xC (even), Sign = 1. 3 Memory addresses in LRUs: 0x1000 holds 0x3F, 0x1001 holds 0xA7, 0x1002 holds 0x5C. 4 Maintenance messages and fault codes on the E/WD page: ENG 1 FAULT (0x2C14), HYD G PRESS LOW (0x3A75), ELEC AC BUS 1 FAULT (0x162B), F/CTL ELAC 1 FAULT (0x1F02). 5 Software and configuration data: SW ID 0xA3201F, CONFIG 0x0003, CHECKSUM 0x7B2C9E4A; bit masks 0x0F = 0000 1111, 0xF0 = 1111 0000, 0xAA = 1010 1010, 0x55 = 0101 0101. A hex quick reference strip maps 0 to F onto 0 to 15.',
   'Infographic năm khung. 1 Nhãn ARINC 429: bảng thông số, nhãn (hex), mô tả: tốc độ không khí 0x00A, độ cao 0x020, hướng 0x082, tốc độ lên xuống 0x07F, OAT 0x0F2; ví dụ nhãn tốc độ = 0x00A. 2 Từ dữ liệu trên ARINC 429: các trường SDI (2 bit), DATA (19 bit), SSM (2 bit), PARITY (1 bit), S (1 bit) từ bit 31 đến bit 0; ví dụ từ dữ liệu (hex) 0x1A3F5BCD với SDI = 0x1, Data = 0xA3F5B, SSM = 0x2, Parity = 0xC (chẵn), Sign = 1. 3 Địa chỉ bộ nhớ trong LRU: 0x1000 chứa 0x3F, 0x1001 chứa 0xA7, 0x1002 chứa 0x5C. 4 Thông báo bảo dưỡng và mã lỗi trên trang E/WD: ENG 1 FAULT (0x2C14), HYD G PRESS LOW (0x3A75), ELEC AC BUS 1 FAULT (0x162B), F/CTL ELAC 1 FAULT (0x1F02). 5 Dữ liệu phần mềm và cấu hình: SW ID 0xA3201F, CONFIG 0x0003, CHECKSUM 0x7B2C9E4A; mặt nạ bit 0x0F = 0000 1111, 0xF0 = 1111 0000, 0xAA = 1010 1010, 0x55 = 0101 0101. Dải tra nhanh hex ánh xạ 0 đến F sang 0 đến 15.',
   numbers=['0x0F = 0000 1111', '0xF0 = 1111 0000', '0xAA = 1010 1010', '0x55 = 0101 0101', '0x1A3F5BCD'],
   issues=['Đã kiểm: bốn mặt nạ bit đúng. Không khớp: các nhãn ARINC 429 trong bảng (0x00A, 0x020, 0x082...) ghi dạng hex, trong khi Module 05 theo Tooley dùng số bát phân cho nhãn (ví dụ nhãn 203 cho tốc độ). Hệ số và giá trị nhãn trong bảng cần đối chiếu tài liệu ARINC, chưa có trong thư mục.',
           'Không khớp: khung từ ghi các trường SDI 2 bit, DATA 19 bit, SSM 2 bit, PARITY 1 bit và thêm một bit dấu S nhưng không có trường nhãn 8 bit; "Parity = 0xC (even)" không thể là một bit. Ví dụ 0x1A3F5BCD phân tích theo các trường này không nhất quán. Cấu trúc đúng của từ 32 bit (Label 8, SDI 2, Data 19, SSM 2, Parity 1) xem Module 05.']),
 s(18, 'content', 'Hexadecimal numbers (binary to hexadecimal)',
   'Binary to hexadecimal: break the binary number into 4-bit groups starting at the rightmost bit and replace each group with the equivalent hexadecimal symbol. Example 1: 110101011110 is grouped 1101 0101 1110 and equals D5E (base 16). Example 2: 1101011110, add two zeros on the left to complete a 4-bit group, 0011 0101 1110, equals 35E (base 16).',
   'Nhị phân sang thập lục phân: chia số nhị phân thành các nhóm 4 bit bắt đầu từ bit ngoài cùng bên phải và thay mỗi nhóm bằng ký hiệu hex tương ứng. Ví dụ 1: 110101011110 chia thành 1101 0101 1110, bằng D5E (cơ số 16). Ví dụ 2: 1101011110, thêm hai số 0 bên trái cho đủ nhóm 4 bit, 0011 0101 1110, bằng 35E (cơ số 16).',
   numbers=['110101011110 = D5E16', '1101011110 = 35E16'], issues=['Đã kiểm: 1101 = D, 0101 = 5, 1110 = E; 0011 = 3. Đúng.']),
 s(19, 'content', 'Hexadecimal numbers (hexadecimal to binary and conclusion)',
   'Hexadecimal to binary: reverse the process and replace each hexadecimal symbol with four bits. Example: find the binary number for a) 35E16, b) A2DF16, c) 10D416. Shown: 3 5 E gives 0011 0101 1110 and A 2 D F gives 1010 0010 1101 1111; part c is not worked on the slide. Conclusion: hexadecimal is a convenient way to represent binary numbers; conversion between hexadecimal and binary is direct and easy; hexadecimal is widely used for representing binary numbers in programming, printouts and displays.',
   'Thập lục phân sang nhị phân: làm ngược lại, thay mỗi ký hiệu hex bằng bốn bit. Ví dụ: tìm số nhị phân của a) 35E16, b) A2DF16, c) 10D416. Slide giải: 3 5 E cho 0011 0101 1110 và A 2 D F cho 1010 0010 1101 1111; ý c không được giải trên slide. Kết luận: hex là cách tiện biểu diễn số nhị phân; đổi giữa hex và nhị phân trực tiếp và dễ; hex dùng rộng rãi để biểu diễn số nhị phân trong lập trình, bản in và màn hình.',
   numbers=['35E16 = 0011 0101 1110', 'A2DF16 = 1010 0010 1101 1111'], issues=['Đã kiểm hai ý a, b. Ý c (10D416 = 0001 0000 1101 0100) không được giải trên slide.']),
 s(20, 'content', 'Octal number',
   'The octal system gives a convenient way to express binary numbers and codes. It has eight digits, 0 to 7. Counting is like decimal except that 8 and 9 are not used: 0, 1, 2, 3, 4, 5, 6, 7, 10, 11, 12, 13, 14, 15, 16, 17, 20, 21, ... Subscript 8 marks octal; example: 14 in octal equals 12 in decimal and C in hexadecimal. Octal to decimal: multiply each digit by its weight and sum; example 1325 (base 8): weights 8^3, 8^2, 8^1, 8^0, so 1x8^3 + 3x8^2 + 2x8^1 + 5x8^0 = 512 + 192 + 16 + 5 = 725 (decimal).',
   'Hệ bát phân cho cách tiện biểu diễn số nhị phân và mã. Có tám chữ số, từ 0 đến 7. Đếm giống thập phân nhưng không dùng 8 và 9: 0, 1, 2, 3, 4, 5, 6, 7, 10, 11, 12, 13, 14, 15, 16, 17, 20, 21, ... Chỉ số dưới 8 đánh dấu bát phân; ví dụ: 14 bát phân bằng 12 thập phân và C hex. Bát phân sang thập phân: nhân mỗi chữ số với trọng số rồi cộng; ví dụ 1325 (cơ số 8): 1x8^3 + 3x8^2 + 2x8^1 + 5x8^0 = 512 + 192 + 16 + 5 = 725 (thập phân).',
   formulas=['1325_8 = 1x8^3 + 3x8^2 + 2x8^1 + 5x8^0 = 512 + 192 + 16 + 5 = 725_10'], numbers=['14_8 = 12_10 = C_16', '1325_8 = 725_10'], issues=['Đã kiểm: 14 bát phân = 8 + 4 = 12; 512 + 192 + 16 + 5 = 725. Đúng.']),
 s(21, 'content', 'Applications of the octal number system in the Airbus A320',
   'Infographic with five panels. 1 Maintenance / system status display: a SYSTEM STATUS page lists FLIGHT CTRL 000237, HYD GREEN 000045, CAB PRESS 000102, ELEC AC BUS 1 000077, APU 000015, all marked OCT. 2 Memory addressing (LRUs): 0000 start of memory, 0001 parameter block 1, 0002 parameter block 2, 0177 end of first page, 0200 start of next page, all octal; octal addresses map to groups of 3 bits. 3 Discrete input/output words: statuses of ON/OFF signals are packed in 3-bit groups; a 16-bit I/O word with bit positions 15 to 0 grouped by 3 bits gives octal digits 3 5 3 2 2 2, I/O WORD (octal) = 353222. 4 Data recording and logging: log words (time UTC, parameter ID, value octal) such as 12:30:15 012 004573, 12:30:16 013 000125, 12:30:17 025 001077. 5 Permission / mode settings: MAINTENANCE 000, TEST 001, NORMAL 002, DEGRADED 003, ENGINEERING 004. An octal-binary reference strip lists 0 = 000, 1 = 001, 3 = 011, 4 = 100, 5 = 101, 6 = 110, 7 = 111.',
   'Infographic năm khung. 1 Hiển thị bảo dưỡng / trạng thái hệ thống: trang SYSTEM STATUS liệt kê FLIGHT CTRL 000237, HYD GREEN 000045, CAB PRESS 000102, ELEC AC BUS 1 000077, APU 000015, đều ghi OCT. 2 Địa chỉ bộ nhớ (LRU): 0000 đầu bộ nhớ, 0001 khối tham số 1, 0002 khối tham số 2, 0177 cuối trang đầu, 0200 đầu trang kế, đều bát phân; địa chỉ bát phân ánh xạ trực tiếp sang nhóm 3 bit. 3 Từ vào/ra rời rạc: trạng thái các tín hiệu ON/OFF được gói thành nhóm 3 bit; từ I/O 16 bit với vị trí bit 15 đến 0 chia theo nhóm 3 bit cho các chữ số bát phân 3 5 3 2 2 2, từ I/O (bát phân) = 353222. 4 Ghi dữ liệu và nhật ký: các từ nhật ký (giờ UTC, mã tham số, giá trị bát phân) như 12:30:15 012 004573, 12:30:16 013 000125, 12:30:17 025 001077. 5 Cài đặt chế độ / quyền: MAINTENANCE 000, TEST 001, NORMAL 002, DEGRADED 003, ENGINEERING 004. Dải tham chiếu bát phân-nhị phân liệt kê 0 = 000, 1 = 001, 3 = 011, 4 = 100, 5 = 101, 6 = 110, 7 = 111.',
   numbers=['0177 bát phân = 127, 0200 bát phân = 128', 'từ I/O 353222 bát phân'],
   issues=['Đã kiểm: 0177 bát phân = 127 và 0200 bát phân = 128, đúng là cuối trang 128 ô và đầu trang kế.',
           'Thiếu sót: dải tham chiếu bát phân-nhị phân ở cuối slide bỏ chữ số 2 (010); bảng đầy đủ ở slide 22.']),
 s(22, 'content', 'Octal number (decimal to octal and octal to binary)',
   'Decimal to octal by repeated division by 8: each division by 8 yields a remainder that becomes a digit of the octal number. Worked: 359/8 = 44 remainder 0.875 so the remainder is 0.875 x 8 = 7; 44/8 = 5 remainder 0.5 so 0.5 x 8 = 4; 5/8 = 0 remainder 0.625 so 0.625 x 8 = 5; stop when the whole-number quotient is zero; octal number 5 4 7 (MSD first, LSD last). Octal to binary: replace each octal digit with three bits; table 0 = 000, 1 = 001, 2 = 010, 3 = 011, 4 = 100, 5 = 101, 6 = 110, 7 = 111.',
   'Thập phân sang bát phân bằng chia 8 liên tiếp: mỗi lần chia 8 cho số dư thành một chữ số của số bát phân. Ví dụ: 359/8 = 44 dư 0,875 nên số dư là 0,875 x 8 = 7; 44/8 = 5 dư 0,5 nên 0,5 x 8 = 4; 5/8 = 0 dư 0,625 nên 0,625 x 8 = 5; dừng khi thương nguyên bằng 0; số bát phân 5 4 7 (chữ số cao nhất trước, thấp nhất sau). Bát phân sang nhị phân: thay mỗi chữ số bát phân bằng ba bit; bảng 0 = 000, 1 = 001, 2 = 010, 3 = 011, 4 = 100, 5 = 101, 6 = 110, 7 = 111.',
   numbers=['359 thập phân = 547 bát phân'], issues=['Đã kiểm: 5x64 + 4x8 + 7 = 359. Đúng.']),
 s(23, 'content', 'Applications of BCD (binary coded decimal) in the Airbus A320',
   'Infographic: BCD codes each decimal digit (0-9) with 4 bits, used for human-readable numbers. 1 Display systems (EFIS, ECAM, SD): EFIS speed 250 kt, ECAM fuel 3200 KG (FOB 3200 KG); 250 decimal = BCD 0010 0101 0000. 2 Data input / control panels (MCDU, FCU): entering FL350 gives BCD of 350 = 0011 0101 0000. 3 Transducer data and ARINC interfaces: sensor, signal conditioning, A/D converter, BCD encoder; pressure 1013 decimal = BCD 0001 0000 0001 0011; BCD words are sent over ARINC 429/717. 4 Maintenance system (CMS): total flight hours 15678 = 0001 0101 0110 0111 1000. 5 Fault codes and status reports: fault code 2103 = 0010 0001 0000 0011. A comparison box BCD versus binary for 59 decimal: BCD 0101 1001 against binary 0011 1011 (6 bits). An ARINC 429 word (BCD example): label 214 (octal), data (BCD) 0010 0001 0100, SSM 11, parity 0. A table "how BCD works" lists digits 0 to 9 with their 4-bit codes. Closing line: BCD is the bridge between binary systems and human operators.',
   'Infographic: BCD mã hoá từng chữ số thập phân (0-9) bằng 4 bit, dùng cho số mà con người đọc. 1 Hệ hiển thị (EFIS, ECAM, SD): tốc độ EFIS 250 kt, nhiên liệu ECAM 3200 KG (FOB 3200 KG); 250 thập phân = BCD 0010 0101 0000. 2 Nhập dữ liệu / bảng điều khiển (MCDU, FCU): nhập FL350, BCD của 350 = 0011 0101 0000. 3 Dữ liệu đầu đo và giao diện ARINC: cảm biến, điều hoà tín hiệu, bộ A/D, bộ mã hoá BCD; áp suất 1013 thập phân = BCD 0001 0000 0001 0011; từ BCD gửi qua ARINC 429/717. 4 Hệ bảo dưỡng (CMS): tổng giờ bay 15678 = 0001 0101 0110 0111 1000. 5 Mã lỗi và báo cáo trạng thái: mã lỗi 2103 = 0010 0001 0000 0011. Khung so sánh BCD với nhị phân cho 59 thập phân: BCD 0101 1001, nhị phân 0011 1011 (6 bit). Một từ ARINC 429 (ví dụ BCD): nhãn 214 (bát phân), dữ liệu (BCD) 0010 0001 0100, SSM 11, parity 0. Bảng "BCD hoạt động thế nào" liệt kê chữ số 0 đến 9 với mã 4 bit. Dòng cuối: BCD là cầu nối giữa hệ nhị phân và người vận hành.',
   numbers=['250 = 0010 0101 0000', '350 = 0011 0101 0000', '1013 = 0001 0000 0001 0011', '15678 = 0001 0101 0110 0111 1000', '2103 = 0010 0001 0000 0011', '59 = BCD 0101 1001 hoặc nhị phân 111011'],
   issues=['Đã kiểm bằng Python: các mã BCD của 250, 350, 1013, 15678, 2103 và 59 đều đúng.']),
 s(24, 'content', 'Octal number (octal to binary and binary to octal examples)',
   'Example: convert 25 (base 8) and 145 (base 8) to binary. Shown: 2 5 gives groups 010 101, so 25(8) = 010101(2). For 1 4 5 the groups are written 010 100 101, so the slide gives 145(8) = 010100101(2). Binary to octal is the reverse of octal to binary. Example: 100101 and 11011 to octal: 100 101 gives digits 4 5 so 45(8); 011 011 gives 3 3 so 33(8).',
   'Ví dụ: đổi 25 (cơ số 8) và 145 (cơ số 8) sang nhị phân. Slide: 2 5 cho các nhóm 010 101, nên 25(8) = 010101(2). Với 1 4 5 các nhóm được viết 010 100 101, nên slide ghi 145(8) = 010100101(2). Nhị phân sang bát phân là ngược lại của bát phân sang nhị phân. Ví dụ: 100101 và 11011 sang bát phân: 100 101 cho chữ số 4 5 nên 45(8); 011 011 cho 3 3 nên 33(8).',
   numbers=['25 bát phân = 010101 nhị phân', '100101 = 45 bát phân', '11011 = 33 bát phân'],
   issues=['LỖI SLIDE (đã xác nhận ở độ phóng đại 4 lần): chữ số 1 của 145(8) được đổi thành 010 thay vì 001. Kết quả slide 010100101(2) thật ra bằng 245(8) (165 thập phân). Đáp án đúng: 145(8) = 001 100 101 = 001100101(2) = 1100101(2).',
           'Đã kiểm: 25(8) = 010101, 100101 = 45(8), 11011 = 33(8) (nhóm từ bên phải thành 011 011). Các ví dụ này đúng.']),
 s(25, 'content', 'Binary coded decimal',
   'BCD is a way to express each decimal digit with a binary code. Applications: digital clocks, digital thermometers, digital meters and other devices with seven-segment displays, which typically use BCD to simplify displaying decimal numbers. There are only ten code groups in the BCD system so converting between decimal and BCD is easy. Each decimal digit 0 to 9 is represented by a four-bit binary code. Table: 0 = 0000, 1 = 0001, 2 = 0010, 3 = 0011, 4 = 0100, 5 = 0101, 6 = 0110, 7 = 0111, 8 = 1000, 9 = 1001.',
   'BCD là cách biểu diễn từng chữ số thập phân bằng mã nhị phân. Ứng dụng: đồng hồ số, nhiệt kế số, đồng hồ đo số và các thiết bị có màn hình 7 đoạn, thường dùng BCD để đơn giản hoá việc hiển thị số thập phân. Hệ BCD chỉ có mười nhóm mã nên đổi giữa thập phân và BCD rất dễ. Mỗi chữ số thập phân 0 đến 9 được biểu diễn bằng mã nhị phân bốn bit. Bảng: 0 = 0000, 1 = 0001, 2 = 0010, 3 = 0011, 4 = 0100, 5 = 0101, 6 = 0110, 7 = 0111, 8 = 1000, 9 = 1001.',
   numbers=['0 = 0000 ... 9 = 1001'], issues=['Đã kiểm bảng 0 đến 9: đúng.']),
 s(26, 'content', 'Binary coded decimal (conversion examples)',
   'Example: convert (a) 35 and (b) 170 to BCD. The slide shows 3 5 with 0010 0101 for (a) and 1 7 0 with 0010 0101 0000 for (b). To find a decimal number from BCD, start at the rightmost bit, break the code into groups of four bits and write the digit of each group. Example: convert to decimal (a) 10000110 = 1000 0110 = 8 6 = 86; (b) 001101010001 = 0011 0101 0001 = 3 5 1 = 351; (c) 1001010001110000 = 1001 0100 0111 0000 = 9 4 7 0 = 9470.',
   'Ví dụ: đổi (a) 35 và (b) 170 sang BCD. Slide ghi 3 5 với 0010 0101 cho (a) và 1 7 0 với 0010 0101 0000 cho (b). Để tìm số thập phân từ BCD, bắt đầu từ bit ngoài cùng bên phải, chia mã thành nhóm bốn bit và viết chữ số của mỗi nhóm. Ví dụ: đổi sang thập phân (a) 10000110 = 1000 0110 = 8 6 = 86; (b) 001101010001 = 0011 0101 0001 = 3 5 1 = 351; (c) 1001010001110000 = 1001 0100 0111 0000 = 9 4 7 0 = 9470.',
   numbers=['10000110 = 86', '001101010001 = 351', '1001010001110000 = 9470'],
   issues=['LỖI SLIDE (đã xác nhận ở độ phóng đại 4 lần): BCD của 35 phải là 0011 0101 nhưng slide in 0010 0101 (đó là BCD của 25). BCD của 170 phải là 0001 0111 0000 nhưng slide in 0010 0101 0000 (đó là BCD của 250), và hai nhóm sau còn bị dính nhau.',
           'Đã kiểm ba ví dụ BCD sang thập phân: 86, 351 và 9470 đều đúng.']),
 s(27, 'thanks', 'Thank you for your attention', 'Closing slide: "Thank you for your attention" with the USTH logo.', 'Slide kết thúc: "Thank you for your attention" (cảm ơn đã chú ý) kèm logo USTH.'),
]
